#include <stdlib.h>
static int cmp218(const void*a,const void*b){int*x=*(int**)a,*y=*(int**)b;if(x[0]!=y[0])return x[0]-y[0];return x[1]-y[1];}
int** getSkyline(int**b,int n,int*cols,int*rs,int**rc){int**ev=malloc(2*n*sizeof(int*));for(int i=0;i<n;i++){ev[2*i]=malloc(2*sizeof(int));ev[2*i][0]=b[i][0];ev[2*i][1]=-b[i][2];ev[2*i+1]=malloc(2*sizeof(int));ev[2*i+1][0]=b[i][1];ev[2*i+1][1]=b[i][2];}qsort(ev,2*n,sizeof(int*),cmp218);int*hs=malloc((n+1)*sizeof(int)),hc=1;hs[0]=0;int**o=malloc(2*n*sizeof(int*)),c=0,prev=0;for(int i=0;i<2*n;i++){int h=ev[i][1];if(h<0)hs[hc++]=-h;else{for(int j=0;j<hc;j++)if(hs[j]==h){hs[j]=hs[--hc];break;}}int mx=0;for(int j=0;j<hc;j++)if(hs[j]>mx)mx=hs[j];if(mx!=prev){o[c]=malloc(2*sizeof(int));o[c][0]=ev[i][0];o[c][1]=mx;c++;prev=mx;}free(ev[i]);}free(ev);free(hs);int*cs=malloc(c*sizeof(int));for(int i=0;i<c;i++)cs[i]=2;*rs=c;*rc=cs;return o;}
